const WORK_START = 9 * 60;
const WORK_END = 18 * 60;
const STEP = 30;
const DURATIONS = { haircut: 30, beard_trim: 20, combo: 45 };

const { date, service } = $('Edit Fields').first().json;
const duration = DURATIONS[service];

if (!duration) {
  return [{ json: { date, service, available_slots: [], error: 'unknown_service' } }];
}

const dow = new Date(`${date}T12:00:00`).getDay();
if (dow === 0) {
  return [{ json: { date, service, available_slots: [], note: 'closed_sunday' } }];
}

const fmt = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Bratislava', hour: '2-digit', minute: '2-digit', hour12: false,
});
const toMin = (iso) => {
  const [h, m] = fmt.format(new Date(iso)).split(':').map(Number);
  return h * 60 + m;
};

const busy = $input.all()
  .map(i => i.json)
  .filter(e => e.start && e.start.dateTime && e.end && e.end.dateTime)
  .map(e => ({ start: toMin(e.start.dateTime), end: toMin(e.end.dateTime) }));

const slots = [];
for (let t = WORK_START; t + duration <= WORK_END; t += STEP) {
  const overlaps = busy.some(b => t < b.end && t + duration > b.start);
  if (!overlaps) {
    const hh = String(Math.floor(t / 60)).padStart(2, '0');
    const mm = String(t % 60).padStart(2, '0');
    slots.push(`${hh}:${mm}`);
  }
}

return [{ json: { date, service, available_slots: slots } }];
